-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ptBR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.druid.balance.Name"] = "Equilíbrio"
L["rm.era.druid.balance.Description"] = "Equilíbrio do nível 1 ao 60, e o padrão do Druida antes dos talentos ou quando nenhuma outra rotação integrada se encaixa. Fogo Estelar como preenchimento depois de aprendido (Ira antes disso, Fogo Estelar primeiro com uma ativação de Graça da Natureza), Fogo Lunar e Nuvem de Insetos mantidos em alvos que vão sobreviver enquanto sua mana estiver acima de 30%, Furacão quando três ou mais inimigos estiverem em você, Fogo Feérico em grupo, instantâneos em movimento, corpo a corpo quando a mana acabar. Na Forma de Felino ou na Forma de Urso, dá as orientações de Combate Feral. Lembretes: Marca do Indomado, Espinhos quando solo, Presságio de Clareza, Forma de Luniscante quando você não está em nenhuma forma, Avivar, Enredamento. Usar graus inferiores de Fogo Estelar, raízes e a escolha de alvo ficam com você."
L["rm.era.druid.balance.icyveins.Name"] = "Equilíbrio (Icy Veins)"
L["rm.era.druid.balance.icyveins.Description"] = "A lista de raide da Icy Veins para reinos com o limite de 16 penalidades, uma alternativa à rotação integrada de Equilíbrio recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Fogo Estelar e nada mais, sem Fogo Lunar nem Nuvem de Insetos, Furacão quando três ou mais inimigos estiverem em você, Ira só antes de aprender Fogo Estelar. Os mesmos lembretes da rotação integrada recomendada."
L["rm.era.druid.feral.Name"] = "Combate Feral"
L["rm.era.druid.feral.Description"] = "Felino e urso de Combate Feral a partir do nível 10, quando Combate Feral é sua árvore de talentos principal; sua forma decide qual. Felino: abertura em furtividade, Fogo Feérico (Feral) mantido, Abstração gasta em Despedaçar, um finalizador a partir de quatro pontos de combo (Rasgar antes de aprender Mordida Feroz e em lutas longas fora de raides, Mordida com menos de 63 de energia), Estraçalhar fora de raides, Despedaçar pelas costas ou Garra quando o alvo está em você, e um powershift (Forma de Felino de novo) quando faltar muita energia, com Furor 5/5 e mana de sobra. Urso: Enfurecer quando faltar raiva, Rugido Desmoralizante em grupos de inimigos e elites a menos que o Brado de um guerreiro esteja ativo, Patada contra dois ou mais inimigos e com raiva de sobra, senão Fogo Feérico (Feral). Forma de lançador: trocar de forma. Lembretes: Malho a cada golpe, Fúria do Tigre antes de puxar, Espanca-gente Manual, Avivar, Regeneração Frenética. O posicionamento fica com você."
L["rm.era.druid.feral.warcrafttavern.Name"] = "Combate Feral (Warcraft Tavern, Rasgar e Mordida)"
L["rm.era.druid.feral.warcrafttavern.Description"] = "A lista com powershifting da Warcraft Tavern, uma alternativa à rotação integrada de Combate Feral recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Rasgar com cinco pontos de combo sempre que estiver ausente, inclusive em raides, depois Mordida Feroz a partir de quatro pontos de combo com menos de 63 de energia, Despedaçar pelas costas, powershift quando faltar muita energia. Urso e lembretes como na rotação integrada recomendada."
L["rm.era.druid.feral.warcrafttavern.casual.Name"] = "Combate Feral (Warcraft Tavern, sem powershifting)"
L["rm.era.druid.feral.warcrafttavern.casual.Description"] = "A lista da Warcraft Tavern sem powershifting, uma alternativa à rotação integrada de Combate Feral recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Acumula até cinco pontos de combo com Despedaçar (Garra pela frente), depois Rasgar em um alvo que vá sobreviver, Fúria do Tigre, Mordida Feroz; caso contrário, espera pela energia. Urso e lembretes como na rotação integrada recomendada."
L["rm.era.druid.feral.wowhead.Name"] = "Combate Feral (urso de raide da Wowhead)"
L["rm.era.druid.feral.wowhead.Description"] = "O felino da rotação integrada de Combate Feral recomendada com o urso de raide equipado da Wowhead: Malho a cada golpe (o Malho com troca de alvo em grupos de inimigos fica por sua conta), Patada só com 60 de raiva de sobra, senão Fogo Feérico (Feral), sem Rugido Desmoralizante e sem Enfurecer em combate. Uma alternativa à rotação integrada de Combate Feral recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela."
L["rm.era.druid.restoration.Name"] = "Restauração"
L["rm.era.druid.restoration.Description"] = "Restauração a partir do nível 10, quando Restauração é sua árvore de talentos principal. Cura seu alvo amigável atual: Toque de Cura após Rapidez da Natureza, Recomposição Rápida abaixo de 40% sobre seu próprio HoT, Rejuvenescer e Recrescimento renovados continuamente, Recrescimento como cura principal com Recrescimento Aprimorado, Toque de Cura completo abaixo de 45% ou com uma ativação de Graça da Natureza, Toque de Cura grau 4 nos demais casos. Em um inimigo: Fogo Lunar, Nuvem de Insetos e Ira. Silenciosa na Forma de Felino ou na Forma de Urso. Lembretes: Marca do Indomado, Presságio de Clareza, Rapidez da Natureza, Tranquilidade, Avivar, Renascimento, remoção de venenos e maldições. A escolha de quem curar fica com você."
L["rm.era.druid.restoration.warcrafttavern.Name"] = "Restauração (Warcraft Tavern)"
L["rm.era.druid.restoration.warcrafttavern.Description"] = "As faixas de dano da Warcraft Tavern, uma alternativa à rotação integrada de Restauração recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. No seu alvo amigável, sem manutenção de HoTs enquanto o dano é baixo: Recomposição Rápida abaixo de 40%, Recrescimento grau 5 abaixo de 50%, Rejuvenescer e Recrescimento grau 3 abaixo de 75%, Toque de Cura completo com uma ativação de Graça da Natureza, Toque de Cura grau 3 abaixo de 90%. Lembretes como na rotação integrada recomendada."
L["rm.forever.druid.balance.Name"] = "Equilíbrio"
L["rm.forever.druid.balance.Description"] = "Equilíbrio do nível 1 ao 60, e o padrão para qualquer Druida do Forever em que nenhuma outra rotação integrada se encaixe (níveis 1–9, lançadores sem talentos, Restauração solo). Puxa com Ira; em movimento, renova Fogo Lunar, Nuvem de Insetos e, em grupo, Fogo Feérico. Furacão quando três ou mais inimigos estão lutando com você, depois seu próprio Fogo Lunar e Nuvem de Insetos, Fogo Estelar enquanto houver cargas de Eclipse ou Abstração, e Ira; quando você não pode pagar por Ira, ele deixa você lutar corpo a corpo. A vida e a mana ficam ocultas dos addons no Forever, então se curar e avaliar se um alvo vale um DoT são decisões suas. Lembretes: Marca do Indomado, Espinhos quando solo, Forma de Luniscante, um Rejuvenescer antes de puxar quando solo, Enredamento quando um monstro está em você, Avivar sempre que estiver pronto em combate quando solo. Trocas de forma, controle de grupo, Pele de Árvore e escolha de alvo ficam com você. Montada a partir de guias do beta de nível 30; os passos dos níveis 31–60 seguem o design da classe e não foram testados."
L["rm.forever.druid.balance.tavern.Name"] = "Equilíbrio, vários DoTs (Warcraft Tavern)"
L["rm.forever.druid.balance.tavern.Description"] = "O estilo de evolução de nível com vários DoTs da Warcraft Tavern, uma alternativa à rotação integrada de Equilíbrio recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Puxa com Ira, mantém seu Fogo Lunar e Nuvem de Insetos no alvo, prende-o com Raízes Enredantes quando ambos estão ativos enquanto outro inimigo luta com você, depois Ira. Sem Fogo Estelar (a build ignora o Eclipse). Trocar para o próximo inimigo fica com você. Lembretes: Marca do Indomado, Espinhos quando solo."
L["rm.forever.druid.feral.Name"] = "Feral, Felino e Urso"
L["rm.forever.druid.feral.Description"] = "Felino e Urso em uma só rotação integrada, escolhidos pela sua forma; ela assume assim que Feral é sua árvore de talentos principal (ou tem 11 pontos), ou quando você muda para Forma de Felino ou de Urso. Felino: Assolar ou Despedaçar a partir de Espreitar, Fogo Feérico, Rasgar com quatro pontos de combo, Mordida Feroz depois que Rasgar estiver ativo, Estraçalhar e depois Despedaçar quando o alvo não está de frente para você (senão Garra). Urso: Fogo Feérico e Investida Feral à distância, Rugido Desmoralizante em grupo ou contra dois inimigos, Mordida Primeva, Patada contra três ou mais, Lacerar, Patada. Em forma de lançador, sugere Forma de Felino (Urso antes de você ter Felino). Lembretes: Malho sempre que você puder pagar por ele em Forma de Urso, Enfurecer, Berserk em puxadas grandes ou elites, Avivar quando solo, Marca do Indomado, Espinhos. A vida, a energia, a raiva e a mana ficam ocultas dos addons no Forever, então trocar de forma para recuperar energia, Regeneração Frenética e se curar são decisões suas. Provocações, interrupções e posicionamento ficam com você."
L["rm.forever.druid.restoration.Name"] = "Restauração"
L["rm.forever.druid.restoration.Description"] = "Cura em grupo segundo a Warcraft Tavern, assim que Restauração é sua árvore de talentos principal com 11 pontos. Cura seu alvo amigável atual: Recomposição Rápida em um alvo com o seu HoT, Crescimento Silvestre, Recrescimento e Rejuvenescer quando ausentes, Toque de Cura. A vida e a mana ficam ocultas dos addons no Forever, então o alvo que você escolhe é o único sinal de quem precisa de cura. Em um alvo hostil: Fogo Lunar, Nuvem de Insetos, Ira. Lembretes: Avivar em combate, Rapidez da Natureza em um alvo amigável em combate, Remover Maldição e Abolir Veneno, Marca do Indomado; Tranquilidade fica com você. Você escolhe quem curar e o grau do feitiço; a Restauração solo usa a rotação integrada de Equilíbrio."
L["rm.forever.druid.restoration.icyveins.Name"] = "Restauração, HoTs primeiro (Icy Veins)"
L["rm.forever.druid.restoration.icyveins.Description"] = "A cura com HoTs primeiro da Icy Veins, uma alternativa à rotação integrada de Restauração recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Em seu alvo amigável: Rejuvenescer, depois Recrescimento quando ausente, Toque de Cura só com os dois HoTs ativos, Recomposição Rápida em um alvo com HoT, depois Crescimento Silvestre (a vida fica oculta no Forever, então o alvo que você escolhe decide quem é curado). Avivar sempre que sair do tempo de recarga. No resto, os mesmos lembretes e a mesma lista para alvos hostis da rotação integrada de Restauração."
L["rm.mop.druid.balance.Name"] = "Recomendada"
L["rm.mop.druid.balance.Description"] = "Recomendada para Equilíbrio a partir do nível 10, segundo a lista da Fase 5 da Wowhead e o simulador. Mantém Fogo Lunar e Fogo Solar ativos e os renova dentro do Eclipse correspondente, lança Chuva Estelar no Eclipse (Lunar), Surto Estelar com Estrelas Cadentes e assim que sair do tempo de recarga, Furacão no Solar ou Tempestade Astral no Lunar contra cinco inimigos, Fogo Estelar durante e depois do Lunar e Ira durante e depois do Solar. O Rotation Master não consegue ler a energia do Eclipse, então entre os Eclipses continua lançando Fogo Estelar se Fogo Estelar foi um dos seus três últimos lançamentos, senão Ira. Lembretes: Marca do Indomado, Forma de Luniscante, Encarnação quando um Eclipse começa e Alinhamento Celestial quando um termina (em elites ou lutas longas), Vigília da Natureza, Força da Natureza, Rapidez da Natureza para Sonho de Cenarius, Avivar, Raio Solar, Pele de Árvore e Renovação com pouca vida. O posicionamento de Cogumelo Selvagem continua manual; o lembrete de Detonar vem desativado por padrão. Para enquanto você lança, viaja, está na Forma de Felino ou na Forma de Urso, ou não tem um inimigo selecionado."
L["rm.mop.druid.feral.Name"] = "Recomendada"
L["rm.mop.druid.feral.Description"] = "Recomendada para Feral a partir do nível 10, segundo o simulador e a lista da Fase 5 da Wowhead. Coloca você na Forma de Felino, abre a partir de Espreitar com Rugido Selvagem e Assolar, mantém Rugido Selvagem ativo, usa Velocidade Predatória para um Toque de Cura com quatro ou cinco pontos de combo com Sonho de Cenarius, Rasgar com cinco pontos (Mordida Feroz o renova abaixo de 25% de vida), Mordida Feroz com cinco pontos enquanto Rasgar e Rugido Selvagem tiverem ambos seis segundos restantes, Estraçalhar, Surra com Abstração, Despedaçar com Abstração ou Berserk quando o alvo não está atacando você (o Rotation Master não consegue saber se você está atrás dele) e Destroçar; Surra e Patada contra quatro inimigos. Na Forma de Urso, dá uma lista curta de tanque. Lembretes: Fúria do Tigre com menos de 35 de energia, Berserk junto com ela em elites ou lutas longas, Encarnação, Força da Natureza, Vigília da Natureza, Esmagar Crânio, Instintos de Sobrevivência e Pele de Árvore com pouca vida, Marca do Indomado. Intercalar Urso e Ira, e Coração das Selvas, continuam manuais."
L["rm.mop.druid.feral.icyveins.Name"] = "Mordida só na faixa de execução (Icy Veins)"
L["rm.mop.druid.feral.icyveins.Description"] = "A ordem de Feral da Icy Veins (a regra de Mordida da Wowhead concorda), uma alternativa à rotação integrada recomendada de Feral: ative esta e desative aquela, ou aumente a prioridade desta. A mesma abertura, Rugido Selvagem, Toque de Cura e dano em área, mas os pontos de combo acima de 25% de vida do alvo vão só para Rasgar e Rugido Selvagem: Mordida Feroz só renova Rasgar na faixa de execução (ou gasta cinco pontos antes de você aprender Rasgar). Estraçalhar é renovado com dois segundos restantes, Surra só com Abstração, e Berserk espera 90 de energia com Fúria do Tigre a pelo menos 15 segundos de distância."
L["rm.mop.druid.guardian.Name"] = "Recomendada"
L["rm.mop.druid.guardian.Description"] = "Recomendada para tanques Guardiões a partir do nível 10, segundo o simulador e a lista da Fase 5 da Wowhead. Coloca você na Forma de Urso, puxa com Fogo Feérico à distância ou Destroçar, mantém Golpes Enfraquecidos com Surra e Armadura Enfraquecida com Fogo Feérico em elites, usa um Toque de Cura de Sonho de Cenarius quando ferido, Destroçar assim que sair do tempo de recarga, Surra e Patada contra três inimigos, depois Lacerar, Surra e Fogo Feérico. Na Forma de Felino (Coração das Selvas), dá uma lista curta de dano. Lembretes: Defesa Selvagem sempre que estiver inativa, Enfurecer para gerar raiva, Regeneração Frenética com pouca vida ou no limite de raiva, Malho acima de 90 de raiva ou com Unhas e Dentes, Pele de Árvore enquanto o alvo ataca você, Instintos de Sobrevivência com pouca vida, Berserk e Encarnação contra dois inimigos ou um chefe, Força da Natureza, Vigília da Natureza, Proteção Cenariana, Esmagar Crânio, Marca do Indomado. Provocar e Poder de Ursoc continuam manuais (os dois lembretes vêm desativados por padrão)."
L["rm.mop.druid.restoration.Name"] = "Recomendada"
L["rm.mop.druid.restoration.Description"] = "Recomendada para Restauração a partir do nível 10, segundo a cura em grupo da Fase 5 da Wowhead. Cura seu alvo amigável atual, ou você mesmo sem alvo; a escolha de quem curar é sua. Recomposição Rápida em um alvo com seu HoT quando ele estiver com pouca vida, quando Harmonia tiver expirado, ou antes de Crescimento Silvestre com Alma da Floresta; Crescimento Silvestre quando três pessoas próximas estiverem feridas; Toque de Cura instantâneo com Rapidez da Natureza; Recrescimento com Abstração ou em um alvo morrendo; Rejuvenescer; depois Toque de Cura e Nutrir enquanto parado. Um alvo atacável recebe Fogo Lunar e Ira. Lembretes: acúmulos de Brotar da Vida e Cascaferro no seu foco (defina o tanque como foco), Cogumelo Selvagem: Florir em dano no grupo, Força da Natureza, Encarnação, Vigília da Natureza, Rapidez da Natureza, Avivar, Cura da Natureza, Proteção Cenariana, Pele de Árvore, Marca do Indomado. Os lembretes de posicionamento de Cogumelo Selvagem, Tranquilidade e Gênese vêm desativados por padrão."
L["rm.mop.druid.restoration.wowhead.Name"] = "Cura de tanque (Wowhead)"
L["rm.mop.druid.restoration.wowhead.Description"] = "A ordem de cura de tanque em alvo único da Wowhead, uma alternativa à rotação integrada recomendada de Restauração para quando você é designado ao tanque: ative esta e desative aquela, ou aumente a prioridade desta. Mantenha o tanque selecionado: ela mantém três Brotar da Vida e Rejuvenescer nele, usa Recrescimento para dano pesado, Nutrir para dano leve, Toque de Cura quando Brotar da Vida e Rejuvenescer estiverem ativos e o tanque estiver abaixo da metade, e Recomposição Rápida para mantê-lo com a vida cheia. Os mesmos lembretes da rotação integrada recomendada."
L["rm.mop.druid.unspecialized.Name"] = "Antes de uma especialização"
L["rm.mop.druid.unspecialized.Description"] = "Para os níveis 1 a 9, ou qualquer druida que ainda não escolheu uma especialização; as rotações integradas de especialização assumem assim que você escolhe uma. Na Forma de Felino, mantém Estraçalhar ativo, gasta cinco pontos de combo (ou dois em um alvo morrendo) em Mordida Feroz e acumula com Destroçar; na Forma de Urso, usa Destroçar e Malho. Nos demais casos, puxa com Ira, mantém Fogo Lunar em alvos que vão durar, lança Ira (Fogo Lunar em movimento) e sugere Rejuvenescer em você mesmo quando você está abaixo de metade da vida e sozinho. Para enquanto você lança, viaja ou não tem um inimigo selecionado."
L["rm.retail.druid.balance.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.druid.balance.Description"] = "Recomendada para Equilíbrio. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, lembretes do que o Assistente de Combate deixa por sua conta: Alinhamento Celestial (ou Encarnação) em combate, Raio Solar em um lançamento interrompível, Forma de Luniscante e Marca do Indomado entre os combates, e Pele de Árvore e sua habilidade racial sempre que estiverem prontas em combate. Lançamentos inimigos ficam ocultos em combate, então Raio Solar só acende onde o jogo os exibe; a vida fica oculta no Retail, então decidir quando usar Pele de Árvore é com você."
L["rm.retail.druid.balance.guide.Name"] = "Referência (Icy Veins, SimulationCraft e Wowhead)"
L["rm.retail.druid.balance.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade de Equilíbrio dos guias. Seus DoTs, Eclipse e ativações ficam ocultos para addons em combate no Midnight, então ela não pode funcionar lá; leia-a ou duplique-a para experimentar. O Poder Astral fica oculto no Retail, então Surto Estelar gasta pelo próprio custo em vez de antes do limite. Puxa com Forma de Luniscante e Ira. Fogo Solar e Fogo Lunar quando ausentes ou prestes a expirar; Eclipse quando nenhum dos dois estiver ativo (Lunar contra três ou mais inimigos, Solar nos demais casos); Chuva Estelar com Urdume do Tece-estrelas, Tocar o Cosmos ou em grupos de inimigos; Surto Estelar com Urdidura do Tece-estrelas ou Tocar o Cosmos; Lua Nova, Meia-lua e Lua Cheia; Cogumelo Selvagem durante um Eclipse; Surto Estelar sempre que você puder pagar por ele; Fogo Estelar durante um Eclipse Lunar ou em grupos de inimigos, senão Ira. Lembretes: Alinhamento Celestial ou Encarnação, Fúria de Eluna e Força da Natureza antes de um Eclipse, Convocar Espíritos durante Alinhamento Celestial, Raio Solar, além dos lembretes utilitários."
L["rm.retail.druid.feral.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.druid.feral.Description"] = "Recomendada para Feral. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, lembretes do que o Assistente de Combate deixa por sua conta: Berserk (ou Encarnação) em combate, Esmagar Crânio em um lançamento interrompível, Instintos de Sobrevivência, Pele de Árvore e sua habilidade racial sempre que estiverem prontos em combate, e Forma de Felino e Marca do Indomado entre os combates. Lançamentos inimigos ficam ocultos em combate, então a interrupção só acende onde o jogo os exibe; a vida fica oculta no Retail, então decidir quando usar as defesas é com você."
L["rm.retail.druid.feral.guide.Name"] = "Referência (Icy Veins e SimulationCraft)"
L["rm.retail.druid.feral.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade de Feral dos guias. Sangramentos e ativações ficam ocultos em combate no Midnight (os pontos de combo não), então ela não pode funcionar lá; a energia fica oculta no Retail. Abre com Forma de Felino, Espreitar e Estraçalhar. Abocanhar; Mordida Feroz com Anseio do Predador-alfa; com cinco pontos de combo, Ira Primeva contra dois ou mais inimigos, Rasgar quando ausente ou em seus últimos segundos, senão Mordida Feroz, esperando energia em vez de acumular além de cinco; abaixo de cinco, Estraçalhar quando ausente ou prestes a expirar, Fogo Lunar de Inspiração Lunar, Patada contra três ou mais inimigos, Despedaçar. Lembretes: Fúria do Tigre sempre que estiver pronta em combate, Berserk ou Encarnação e Frenesi Feral ou Frenesi Frenético (com dois pontos ou menos) durante Fúria do Tigre, Convocar Espíritos durante Fúria do Tigre e Berserk com Rasgar ativo, Esmagar Crânio, Instintos de Sobrevivência, além dos lembretes utilitários. O snapshotting fica com você."
L["rm.retail.druid.guardian.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.druid.guardian.Description"] = "Recomendada para Guardião. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; o Assistente de Combate joga apenas para causar dano. Junto a isso, lembretes do que ele deixa por sua conta: Berserk (ou Encarnação) e Convocar Espíritos em combate, Veloférreo, Regeneração Frenética, Instintos de Sobrevivência, Pele de Árvore e sua habilidade racial sempre que estiverem prontos em combate, Esmagar Crânio em um lançamento interrompível, e Forma de Urso e Marca do Indomado entre os combates. Lançamentos inimigos ficam ocultos em combate, então Esmagar Crânio só acende onde o jogo os exibe; a vida e a raiva ficam ocultas no Retail, então decidir quando usar as defesas é com você e Veloférreo não pode esperar por um limiar de raiva."
L["rm.retail.druid.guardian.guide.Name"] = "Referência (Icy Veins e Wowhead)"
L["rm.retail.druid.guardian.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade de Guardião dos guias. Penalidades e ativações ficam ocultas em combate no Midnight, então ela não pode funcionar lá; a raiva e a vida ficam ocultas no Retail, então o descarte de Arrasar e Espancar com 80 de raiva fica com você. Surra e Destroçar assim que saírem do tempo de recarga, Lua Vermelha contra um único alvo, Fogo Lunar quando ausente ou com Guardião Galáctico, Patada. Lembretes sempre que estiverem prontos em combate: Veloférreo, Regeneração Frenética, Instintos de Sobrevivência; Forma de Urso entre os combates; Berserk ou Encarnação, Feixe Lunar, Convocar Espíritos, Coração das Selvas, Esmagar Crânio, além dos lembretes utilitários."
L["rm.retail.druid.guardian.simc.Name"] = "Referência defensiva (SimulationCraft)"
L["rm.retail.druid.guardian.simc.Description"] = "Apenas referência, desativada por padrão: a lista de Guardião do SimulationCraft, que gasta raiva primeiro em Veloférreo. Os dados de combate ocultos a impedem de funcionar em combate no Midnight, e a raiva fica oculta no Retail, então os limiares de raiva ficam de fora. Veloférreo durante Berserk; Surra quando ausente, prestes a expirar ou abaixo de três acúmulos; Espancar com Pelo Ensanguentado; Surra contra três ou mais inimigos; Destroçar enquanto Lua Vermelha causa dano; Lua Vermelha; Destroçar; Surra; Fogo Lunar; Patada. A alternância com a Forma de Felino fica de fora. Lembretes: Forma de Urso, Regeneração Frenética, Instintos de Sobrevivência, Berserk ou Encarnação, Feixe Lunar, Convocar Espíritos, Esmagar Crânio, além dos lembretes utilitários."
L["rm.retail.druid.initial.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.druid.initial.Description"] = "Recomendada antes de você escolher uma especialização (enquanto o jogo informa a especialização inicial do Druida). Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, os lembretes que toda rotação integrada de Druida compartilha, cada um assim que você conhece o feitiço dele. Quando você escolhe uma especialização no nível 10, as rotações integradas dessa especialização assumem."
L["rm.retail.druid.restoration.Name"] = "Assistente de Combate da Blizzard com manutenção"
L["rm.retail.druid.restoration.Description"] = "Recomendada para Restauração. Com um inimigo como alvo, destaca a sugestão do Assistente de Combate da Blizzard, a lista de dano de Restauração da própria Blizzard em Forma de Felino ou na forma normal. Caso contrário, sugere os lançamentos de manutenção da Icy Veins no seu alvo amigável (ou em você): Brotar da Vida, Eflorescência em combate, Recomposição Rápida em um alvo com Rejuvenescer, Crescimento Silvestre em grupo em combate, Recrescimento com Abstração ou cinco acúmulos de Abundância, Rejuvenescer quando ausente. A vida e a mana ficam ocultas no Retail, então esses passos seguem o alvo que você escolhe, não o quanto alguém está ferido; suas curas periódicas ficam ocultas em combate no Midnight, então os passos que as leem aguardam lá. Quem curar, e todos os tempos de recarga de cura, ficam com você. Lembretes: Avivar, Pele de Árvore e sua habilidade racial sempre que estiverem prontos em combate, Marca do Indomado entre os combates."
L["rm.sod.druid.balance.Name"] = "Equilíbrio (SoD)"
L["rm.sod.druid.balance.Description"] = "Equilíbrio da Temporada da Descoberta do nível 1 ao 60, e o padrão para qualquer Druida em que nenhuma outra rotação integrada da Temporada da Descoberta se encaixe. Surto Estelar sempre que o bônus dele estiver ausente, Fogo Solar e Fogo Lunar em alvos que vão sobreviver, Fogo Estelar só quando Surto Estelar ou Eclipse: Lunar o fortalecer, Ira como preenchimento, Furacão contra seis ou mais inimigos (quatro com Ventos Tormentosos gravado), Nuvem de Insetos só em movimento. As runas são usadas conforme você as grava. Na Forma de Felino ou na Forma de Urso, dá as orientações de Combate Feral. Lembretes: Forma de Luniscante, Chuva Estelar, Toque de Cura instantâneo em um aliado morrendo, remoção de maldições e venenos, Crescimento Silvestre em um grupo ferido, Avivar. Espalhar DoTs para outros alvos fica com você."
L["rm.sod.druid.balance.icyveins.Name"] = "Equilíbrio (SoD, Icy Veins)"
L["rm.sod.druid.balance.icyveins.Description"] = "A lista da Temporada da Descoberta da Icy Veins, uma alternativa à rotação integrada de Equilíbrio da Temporada da Descoberta recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Surto Estelar assim que sair do tempo de recarga, Furacão contra quatro ou mais inimigos (por Ventos Tormentosos), Fogo Estelar quando Surto Estelar o fortalecer, Fogo Lunar, Fogo Solar e Nuvem de Insetos todos mantidos, Ira como preenchimento. Lembretes como na rotação integrada recomendada."
L["rm.sod.druid.balance.wowhead.Name"] = "Equilíbrio (SoD, Wowhead)"
L["rm.sod.druid.balance.wowhead.Description"] = "A lista da Fase 8 da Wowhead, uma alternativa à rotação integrada de Equilíbrio da Temporada da Descoberta recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Ira para abrir, Surto Estelar assim que sair do tempo de recarga, Furacão contra seis ou mais inimigos, Nuvem de Insetos só em movimento, Fogo Solar e Fogo Lunar mantidos, Ira enquanto seu Fogo Solar tiver menos de 5 segundos quando Chamas de Eluna estiver gravado para prolongá-lo, Fogo Estelar com Eclipse: Lunar, senão Ira. Lembretes como na rotação integrada recomendada."
L["rm.sod.druid.feral.Name"] = "Combate Feral, felino (SoD)"
L["rm.sod.druid.feral.Description"] = "Felino da Temporada da Descoberta, escolhida quando Rugido Selvagem está gravado (ou quando Combate Feral é sua árvore principal sem outra runa de pernas). Fogo Feérico (Feral) quando nenhum estiver ativo, Rugido Selvagem, Patada (Felino) contra quatro ou mais inimigos, a penalidade de Destroçar, Abstração em Despedaçar, Rasgar com cinco pontos de combo enquanto Rugido Selvagem tiver 8 segundos restantes, Estraçalhar, Despedaçar pelas costas ou Destroçar pela frente, powershift com Furor 5/5, renovação de Fogo Feérico por último. Na Forma de Urso, dá as orientações de tanque. Lembretes: Fúria do Tigre com 60 de energia ou menos, Berserk com Fúria do Tigre, Malho, Avivar. O posicionamento fica com você."
L["rm.sod.druid.restoration.Name"] = "Restauração (SoD)"
L["rm.sod.druid.restoration.Description"] = "Restauração da Temporada da Descoberta, escolhida quando Brotar da Vida está gravado (ou quando Restauração é sua árvore principal sem outra runa de pernas). Cura seu alvo amigável atual: Toque de Cura instantâneo após Rapidez da Natureza ou Fúria de Tempesfúria, Crescimento Silvestre quando dois ou mais aliados próximos estiverem feridos, Recomposição Rápida sobre seu HoT para Eflorescência ou abaixo de 40%, três acúmulos de Brotar da Vida renovados com um segundo restante, Rejuvenescer, Recrescimento abaixo de 60%, Nutrir, Toque de Cura grau 4. Em um inimigo: Fogo Solar, Fogo Lunar, Ira. Lembretes: Árvore da Vida e Instintos de Sobrevivência em momentos pesados, Rapidez da Natureza, Tranquilidade, Avivar, Renascimento, Reviver, dissipações. A escolha de quem curar fica com você."
L["rm.sod.druid.tank.Name"] = "Tanque urso (SoD)"
L["rm.sod.druid.tank.Description"] = "Tanque urso da Temporada da Descoberta, escolhida quando Lacerar está gravado. Fogo Feérico (Feral) ou Fogo Solar (Urso) para puxar à distância, Lacerar antes de expirar, Destroçar assim que sair do tempo de recarga, Lacerar, Patada; contra três ou mais inimigos, Destroçar sob Berserk e Patada. Na Forma de Felino, segue a lista do felino para tanque secundário; na forma de lançador, troca para Urso. Lembretes: Malho com 30 de raiva, Berserk, Instintos de Sobrevivência, Regeneração Frenética e Pele de Árvore com pouca vida, Enfurecer entre as puxadas, Rugido Desmoralizante em elites. Provocar e a escolha de alvo ficam com você."
L["rm.sod.druid.tank.simulator.Name"] = "Tanque urso (SoD, intercalação de felino do simulador)"
L["rm.sod.druid.tank.simulator.Description"] = "Desativada por padrão; para especialistas cujo equipamento também concede Rugido Selvagem. A intercalação de felino da Fase 7 do simulador: sai do Urso para o Felino quando seu Estraçalhar expirar, mantém Rugido Selvagem e Estraçalhar ativos (Fúria do Tigre, Destroçar para acumular), depois volta para Urso Hediondo e segue a lista de tanque. Lembretes como na rotação integrada recomendada de tanque."
L["rm.tbc.druid.balance.Name"] = "Equilíbrio"
L["rm.tbc.druid.balance.Description"] = "Equilíbrio lançador do nível 1 ao 70, e o padrão para qualquer Druida em que nenhuma outra rotação integrada se encaixe. Puxa com Fogo Estelar (Ira antes do 20), Nuvem de Insetos e Fogo Lunar em movimento, Fogo Feérico em grupo, Furacão para três ou mais inimigos, Fogo Lunar quando tiver expirado e você tiver 30% de mana, Fogo Estelar com Graça da Natureza, Ira contra um alvo corpo a corpo e depois Fogo Estelar (Ira antes de aprendê-lo). Nenhuma sugestão nas formas de Felino, Urso ou de viagem. Lembretes: Marca do Indomado, Espinhos quando solo, Presságio de Clareza, Forma de Luniscante, Força da Natureza em uma luta longa, Avivar quando a mana estiver baixa."
L["rm.tbc.druid.feral.icyveins.Name"] = "Combate Feral (Icy Veins, Warcraft Tavern & simulador)"
L["rm.tbc.druid.feral.icyveins.Description"] = "Felino e urso para a árvore Combate Feral, seguindo sua forma. Felino: abertura em furtividade (Pulo do Gato, Assolar ou Despedaçar), Fogo Feérico (Feral), Rasgar com quatro pontos de combo em um alvo que vá sobreviver, Mordida Feroz entre os Rasgares sem Abstração, Triturar mantido, Despedaçar pelas costas ou Triturar/Garra quando o alvo está em você. Urso: Fogo Feérico, Lacerar renovado antes de expirar, Rugido Desmoralizante a menos que o Brado de um guerreiro esteja ativo, Patada para grupos de inimigos, Triturar, cinco Lacerar, Patada. Em forma de lançador, sugere Forma de Felino (ou de Urso). Lembretes: Marca, Espinhos, Presságio, Malho com raiva de sobra, Fúria do Tigre antes de puxar, Regeneração Frenética. O powershifting é um passo opcional que começa desativado (exige uma macro de powershift)."
L["rm.tbc.druid.feral.wowhead.Name"] = "Combate Feral (Wowhead)"
L["rm.tbc.druid.feral.wowhead.Description"] = "O Feral da Wowhead, uma alternativa à rotação integrada de Feral da Icy Veins recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Rasgar sempre que estiver ausente com quatro pontos de combo e Mordida Feroz só em um alvo prestes a morrer (sem intercalar Mordidas); ursos gastam os tempos de recarga globais livres em Lacerar antes de Patada. Avivar quando um felino fica com pouca mana. No resto, igual à variante Icy Veins."
L["rm.tbc.druid.restoration.Name"] = "Restauração"
L["rm.tbc.druid.restoration.Description"] = "Cura para a árvore Restauração no seu alvo amigável (ou em você mesmo): Toque de Cura após Rapidez da Natureza, Recomposição Rápida em um alvo morrendo que tenha seu Rejuvenescer ou Recrescimento, três Brotar da Vida renovados continuamente em combate, Rejuvenescer e Recrescimento quando ausentes, depois Recrescimento em Árvore da Vida ou Toque de Cura fora dela. Um alvo hostil recebe Fogo Lunar e Ira para jogar solo. Lembretes: Marca, Presságio, Árvore da Vida, Rapidez da Natureza, Tranquilidade, Avivar e Renascimento. A escolha de quem curar e o uso de graus inferiores ficam com você."
